#!/usr/bin/env node
// patch.mjs
//
// Applies the "track / win-loss / history / MongoDB / candle-close gate"
// upgrade to your chart-entry-analyzer project. Run from the project root:
//
//   node patch.mjs
//
// It backs up every file it touches into .patch-backup/<timestamp>/ before
// writing anything, so nothing is lost if you want to revert.

import fs from "fs";
import path from "path";

const ROOT = process.cwd();
const STAMP = new Date().toISOString().replace(/[:.]/g, "-");
const BACKUP_DIR = path.join(ROOT, ".patch-backup", STAMP);

const NEW_SERVER_JS = Buffer.from(
  "",
  "base64"
).toString("utf8");

const NEW_APP_JSX = Buffer.from(
  "",
  "base64"
).toString("utf8");

function backupIfExists(relPath) {
  const abs = path.join(ROOT, relPath);
  if (!fs.existsSync(abs)) return false;
  const dest = path.join(BACKUP_DIR, relPath);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.copyFileSync(abs, dest);
  return true;
}

function writeFile(relPath, content) {
  const abs = path.join(ROOT, relPath);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, content, "utf8");
  console.log("  wrote " + relPath);
}

function findAppJsxPath() {
  // Prefer src/App.jsx (matches index.html's /src/main.jsx), fall back to
  // App.jsx at the project root if that's where it actually lives.
  if (fs.existsSync(path.join(ROOT, "src", "App.jsx"))) return "src/App.jsx";
  if (fs.existsSync(path.join(ROOT, "App.jsx"))) return "App.jsx";
  return "src/App.jsx"; // default location if neither exists yet
}

function patchPackageJson() {
  const relPath = "package.json";
  const abs = path.join(ROOT, relPath);
  if (!fs.existsSync(abs)) {
    console.log("  ! package.json not found, skipping dependency patch");
    return;
  }
  backupIfExists(relPath);
  const pkg = JSON.parse(fs.readFileSync(abs, "utf8"));
  pkg.dependencies = pkg.dependencies || {};
  pkg.dependencies.mongoose = pkg.dependencies.mongoose || "^8.6.0";
  pkg.dependencies.dotenv = pkg.dependencies.dotenv || "^16.4.5";
  fs.writeFileSync(abs, JSON.stringify(pkg, null, 2) + "\n", "utf8");
  console.log("  wrote package.json (added mongoose, dotenv)");
}

function patchEnvExample() {
  // Handle either .env.example or _env.example naming.
  const candidates = [".env.example", "_env.example"];
  const relPath = candidates.find((p) => fs.existsSync(path.join(ROOT, p))) || ".env.example";
  const abs = path.join(ROOT, relPath);

  let contents = fs.existsSync(abs) ? fs.readFileSync(abs, "utf8") : "";
  if (fs.existsSync(abs)) backupIfExists(relPath);

  if (!contents.includes("MONGODB_URI")) {
    if (contents.length && !contents.endsWith("\n")) contents += "\n";
    contents += "MONGODB_URI=mongodb://localhost:27017/traderapp\n";
  }
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, contents, "utf8");
  console.log("  wrote " + relPath + " (added MONGODB_URI)");
}

console.log("Chart Entry Analyzer -- patch");
console.log("Backing up touched files to " + path.relative(ROOT, BACKUP_DIR) + "/\n");

console.log("1. server.js (adds MongoDB + trade routes)");
backupIfExists("server.js");
writeFile("server.js", NEW_SERVER_JS);

console.log("\n2. App.jsx (adds track / win-loss / history / candle-close gate)");
const appJsxRel = findAppJsxPath();
backupIfExists(appJsxRel);
writeFile(appJsxRel, NEW_APP_JSX);

console.log("\n3. package.json (adds mongoose, dotenv)");
patchPackageJson();

console.log("\n4. env example (adds MONGODB_URI)");
patchEnvExample();

console.log("\nDone.\n");
console.log("Next steps:");
console.log("  1. npm install");
console.log("  2. Make sure MONGODB_URI is set in your real .env");
console.log("     (defaults to mongodb://localhost:27017/traderapp if you skip this)");
console.log("  3. npm run dev   (or npm run build && npm start)");
console.log("");
console.log("Originals of every file this touched were saved under:");
console.log("  " + path.relative(ROOT, BACKUP_DIR) + "/");
